// ❌ OLD: Running a CPU-heavy operation on the main thread freezes
// the entire process. While expensiveParse() runs (maybe 200ms), no
// other request, timer, or event is processed — every user's request
// waits. This is the classic 'event loop blocked' incident.
const http = require('node:http');

http.createServer((req, res) => {
  const result = expensiveParse(hugeData); // ❌ OLD: blocks all requests
  res.end(result);
}).listen(3000);

// At 50ms of CPU per request, this server can only do ~20 req/s, and
// a single slow request stalls everyone.

// ✅ NEW: The CPU-heavy parse runs on a separate worker thread, so
// the event loop stays free to serve other requests.
const { Worker } = require('node:worker_threads');
const http = require('node:http');

http.createServer((req, res) => {
  const worker = new Worker('./parse-worker.js'); // ✅ NEW: separate isolate
  worker.postMessage(hugeData); // ✅ NEW: structured clone (or transfer)
  worker.once('message', (result) => {
    worker.terminate();
    res.end(result);
  });
  worker.once('error', (err) => {
    worker.terminate();
    res.statusCode = 500;
    res.end(String(err));
  });
}).listen(3000);

